     1→/**
     2→ * CLAUDELang v6.0 기본 테스트
     3→ */
     4→
     5→const CLAUDELangCompiler = require("../src/compiler.js");
     6→
     7→// 색상 정의
     8→const colors = {
     9→  reset: "\x1b[0m",
    10→  green: "\x1b[32m",
    11→  red: "\x1b[31m",
    12→  yellow: "\x1b[33m",
    13→  blue: "\x1b[34m",
    14→};
    15→
    16→class TestRunner {
    17→  constructor() {
    18→    this.passed = 0;
    19→    this.failed = 0;
    20→    this.compiler = new CLAUDELangCompiler();
    21→  }
    22→
    23→  test(name, fn) {
    24→    try {
    25→      fn();
    26→      console.log(`${colors.green}✅ PASS${colors.reset}: ${name}`);
    27→      this.passed++;
    28→    } catch (error) {
    29→      console.log(`${colors.red}❌ FAIL${colors.reset}: ${name}`);
    30→      console.log(`   ${error.message}`);
    31→      this.failed++;
    32→    }
    33→  }
    34→
    35→  assert(condition, message) {
    36→    if (!condition) {
    37→      throw new Error(message);
    38→    }
    39→  }
    40→
    41→  assertEqual(actual, expected, message) {
    42→    if (actual !== expected) {
    43→      throw new Error(
    44→        `${message} - expected '${expected}', got '${actual}'`
    45→      );
    46→    }
    47→  }
    48→
    49→  summary() {
    50→    const total = this.passed + this.failed;
    51→    console.log(`\n${colors.blue}═══════════════════════════${colors.reset}`);
    52→    console.log(`${colors.blue}테스트 결과${colors.reset}`);
    53→    console.log(`${colors.blue}═══════════════════════════${colors.reset}`);
    54→    console.log(`전체: ${total}`);
    55→    console.log(`${colors.green}성공: ${this.passed}${colors.reset}`);
    56→    console.log(`${colors.red}실패: ${this.failed}${colors.reset}`);
    57→    console.log(`${colors.blue}═══════════════════════════${colors.reset}\n`);
    58→
    59→    return this.failed === 0;
    60→  }
    61→}
    62→
    63→// 테스트 실행
    64→const runner = new TestRunner();
    65→
    66→console.log(`\n${colors.yellow}CLAUDELang v6.0 기본 테스트${colors.reset}\n`);
    67→
    68→// ====== Test 1: 기본 변수 선언 ======
    69→runner.test("Test 1: 기본 변수 선언", () => {
    70→  const program = {
    71→    version: "6.0",
    72→    instructions: [
    73→      {
    74→        type: "var",
    75→        name: "x",
    76→        value_type: "i32",
    77→        value: 42,
    78→      },
    79→    ],
    80→  };
    81→
    82→  const result = runner.compiler.compile(program);
    83→  runner.assert(result.success, "컴파일 실패");
    84→  runner.assert(result.code.includes("(define x 42)"), "생성된 코드에 변수 선언이 없음");
    85→});
    86→
    87→// ====== Test 2: 문자열 변수 ======
    88→runner.test("Test 2: 문자열 변수 선언", () => {
    89→  const program = {
    90→    version: "6.0",
    91→    instructions: [
    92→      {
    93→        type: "var",
    94→        name: "message",
    95→        value_type: "string",
    96→        value: "Hello",
    97→      },
    98→    ],
    99→  };
   100→
   101→  const result = runner.compiler.compile(program);
   102→  runner.assert(result.success, "컴파일 실패");
   103→  runner.assert(
   104→    result.code.includes('(define message "Hello")'),
   105→    "문자열이 제대로 생성되지 않음"
   106→  );
   107→});
   108→
   109→// ====== Test 3: 배열 ======
   110→runner.test("Test 3: 배열 선언", () => {
   111→  const program = {
   112→    version: "6.0",
   113→    instructions: [
   114→      {
   115→        type: "var",
   116→        name: "numbers",
   117→        value_type: "Array<i32>",
   118→        value: {
   119→          type: "array",
   120→          elements: [
   121→            { type: "literal", value_type: "i32", value: 1 },
   122→            { type: "literal", value_type: "i32", value: 2 },
   123→            { type: "literal", value_type: "i32", value: 3 },
   124→          ],
   125→        },
   126→      },
   127→    ],
   128→  };
   129→
   130→  const result = runner.compiler.compile(program);
   131→  runner.assert(result.success, "컴파일 실패");
   132→  runner.assert(
   133→    result.code.includes("(define numbers"),
   134→    "배열 변수 선언이 없음"
   135→  );
   136→  runner.assert(result.code.includes("(array"), "배열 생성이 없음");
   137→});
   138→
   139→// ====== Test 4: 함수 호출 ======
   140→runner.test("Test 4: 함수 호출", () => {
   141→  const program = {
   142→    version: "6.0",
   143→    instructions: [
   144→      {
   145→        type: "call",
   146→        function: "print",
   147→        args: [
   148→          { type: "literal", value_type: "string", value: "Hello" },
   149→        ],
   150→      },
   151→    ],
   152→  };
   153→
   154→  const result = runner.compiler.compile(program);
   155→  runner.assert(result.success, "컴파일 실패");
   156→  runner.assert(
   157→    result.code.includes("(call print"),
   158→    "함수 호출이 없음"
   159→  );
   160→});
   161→
   162→// ====== Test 5: 산술 연산 ======
   163→runner.test("Test 5: 산술 연산", () => {
   164→  const program = {
   165→    version: "6.0",
   166→    instructions: [
   167→      {
   168→        type: "var",
   169→        name: "a",
   170→        value_type: "i32",
   171→        value: 10,
   172→      },
   173→      {
   174→        type: "var",
   175→        name: "b",
   176→        value_type: "i32",
   177→        value: 20,
   178→      },
   179→      {
   180→        type: "call",
   181→        function: "print",
   182→        args: [
   183→          {
   184→            type: "arithmetic",
   185→            operator: "+",
   186→            left: { type: "ref", name: "a" },
   187→            right: { type: "ref", name: "b" },
   188→          },
   189→        ],
   190→      },
   191→    ],
   192→  };
   193→
   194→  const result = runner.compiler.compile(program);
   195→  runner.assert(result.success, "컴파일 실패");
   196→  runner.assert(result.code.includes("(+ a b)"), "산술 연산이 없음");
   197→});
   198→
   199→// ====== Test 6: 조건문 ======
   200→runner.test("Test 6: 조건문 (if-then-else)", () => {
   201→  const program = {
   202→    version: "6.0",
   203→    instructions: [
   204→      {
   205→        type: "condition",
   206→        test: {
   207→          type: "comparison",
   208→          operator: ">",
   209→          left: { type: "literal", value_type: "i32", value: 10 },
   210→          right: { type: "literal", value_type: "i32", value: 5 },
   211→        },
   212→        then: [
   213→          {
   214→            type: "call",
   215→            function: "print",
   216→            args: [
   217→              { type: "literal", value_type: "string", value: "true" },
   218→            ],
   219→          },
   220→        ],
   221→        else: [
   222→          {
   223→            type: "call",
   224→            function: "print",
   225→            args: [
   226→              { type: "literal", value_type: "string", value: "false" },
   227→            ],
   228→          },
   229→        ],
   230→      },
   231→    ],
   232→  };
   233→
   234→  const result = runner.compiler.compile(program);
   235→  runner.assert(result.success, "컴파일 실패");
   236→  runner.assert(result.code.includes("(if"), "if 문이 없음");
   237→  runner.assert(result.code.includes("(> 10 5)"), "비교 연산이 없음");
   238→});
   239→
   240→// ====== Test 7: 반복문 ======
   241→runner.test("Test 7: 반복문 (for loop)", () => {
   242→  const program = {
   243→    version: "6.0",
   244→    instructions: [
   245→      {
   246→        type: "var",
   247→        name: "items",
   248→        value_type: "Array<i32>",
   249→        value: {
   250→          type: "array",
   251→          elements: [
   252→            { type: "literal", value_type: "i32", value: 1 },
   253→            { type: "literal", value_type: "i32", value: 2 },
   254→          ],
   255→        },
   256→      },
   257→      {
   258→        type: "loop",
   259→        iterator: "item",
   260→        range: { type: "ref", name: "items" },
   261→        body: [
   262→          {
   263→            type: "call",
   264→            function: "print",
   265→            args: [{ type: "ref", name: "item" }],
   266→          },
   267→        ],
   268→      },
   269→    ],
   270→  };
   271→
   272→  const result = runner.compiler.compile(program);
   273→  runner.assert(result.success, "컴파일 실패");
   274→  runner.assert(result.code.includes("(for item"), "for 루프가 없음");
   275→});
   276→
   277→// ====== Test 8: 람다 함수 ======
   278→runner.test("Test 8: 람다 함수", () => {
   279→  const program = {
   280→    version: "6.0",
   281→    instructions: [
   282→      {
   283→        type: "var",
   284→        name: "numbers",
   285→        value_type: "Array<i32>",
   286→        value: {
   287→          type: "array",
   288→          elements: [
   289→            { type: "literal", value_type: "i32", value: 1 },
   290→            { type: "literal", value_type: "i32", value: 2 },
   291→          ],
   292→        },
   293→      },
   294→      {
   295→        type: "call",
   296→        function: "Array.map",
   297→        args: [
   298→          { type: "ref", name: "numbers" },
   299→          {
   300→            type: "lambda",
   301→            params: [{ name: "x", type: "i32" }],
   302→            body: [
   303→              {
   304→                type: "arithmetic",
   305→                operator: "*",
   306→                left: { type: "ref", name: "x" },
   307→                right: { type: "literal", value_type: "i32", value: 2 },
   308→              },
   309→            ],
   310→          },
   311→        ],
   312→        assign_to: "result",
   313→      },
   314→    ],
   315→  };
   316→
   317→  const result = runner.compiler.compile(program);
   318→  runner.assert(result.success, "컴파일 실패");
   319→  runner.assert(result.code.includes("(fn"), "람다 함수가 없음");
   320→  runner.assert(result.code.includes("Array.map"), "Array.map 호출이 없음");
   321→});
   322→
   323→// ====== Test 9: 타입 에러 감지 ======
   324→runner.test("Test 9: 타입 에러 감지", () => {
   325→  const program = {
   326→    version: "6.0",
   327→    instructions: [
   328→      {
   329→        type: "var",
