   336→
   337→  const result = runner.compiler.compile(program);
   338→  runner.assert(!result.success, "타입 에러를 감지하지 못함");
   339→  runner.assert(result.errors.length > 0, "에러 메시지가 없음");
   340→});
   341→
   342→// ====== Test 10: 주석 ======
   343→runner.test("Test 10: 주석 지원", () => {
